import{c as a,Q as n,j as s,m as l}from"./chunks/framework.BPKcPtvA.js";const p="/term-keeper/confirmation-table-flow.png",t="/term-keeper/demo-glossary-table.png",u=JSON.parse('{"title":"别再让 Agent 忘记项目术语","description":"","frontmatter":{},"headers":[],"relativePath":"blog/term-keeper-agent-glossary.md","filePath":"blog/term-keeper-agent-glossary.md","lastUpdated":null}'),i={name:"blog/term-keeper-agent-glossary.md"};function r(o,e,d,c,h,g){return n(),s("div",null,[...e[0]||(e[0]=[l('<h1 id="别再让-agent-忘记项目术语" tabindex="-1">别再让 Agent 忘记项目术语 <a class="header-anchor" href="#别再让-agent-忘记项目术语" aria-label="Permalink to &quot;别再让 Agent 忘记项目术语&quot;">​</a></h1><div class="spring-meta"><span>agent-workflow</span><span>codex-skill</span><span>term-keeper</span></div><p>如果你在一个项目里长期使用 Agent，应该很容易遇到这种情况：同一个模块名、指标名、角色边界，明明前面已经解释过，换一轮对话之后又要重新确认一遍。</p><p>有时是上下文压缩之后，Agent 忘了关键定义；有时是不同 Agent 对同一个词的理解不一致；有时是临时运行状态被误当成长期概念。更麻烦的是，每次纠正都不只是多说两句话，它会打断当前任务，把时间重新花在“我们刚才说的这个词到底是什么意思”上。</p><p>我最近整理的 <strong>Agent 词典管家 term-keeper</strong>，就是为了解决这个问题。它不试图让 Agent 变得更聪明，而是给项目加一层稳定的词义记忆：把长期术语沉淀到项目文件里，并且让 Agent 在写入前先向用户确认。</p><h2 id="问题不是没有记忆-而是记忆没有边界" tabindex="-1">问题不是没有记忆，而是记忆没有边界 <a class="header-anchor" href="#问题不是没有记忆-而是记忆没有边界" aria-label="Permalink to &quot;问题不是没有记忆，而是记忆没有边界&quot;">​</a></h2><p>使用 Agent 做长期项目时，最容易漂移的通常不是代码本身，而是项目里的“语义”。</p><p>比如：</p><ul><li>某个模块名到底代表一个页面、一个服务，还是一个处理阶段。</li><li>某个 Agent 角色负责什么，不负责什么。</li><li>某个报表字段使用哪个数据源，展示口径是什么。</li><li>某个流水线状态是业务状态、技术状态，还是临时运行状态。</li><li>某个旧说法是否已经废弃，后续是否还能继续使用。</li></ul><p>这些信息不一定适合写进 README，因为 README 面向的是项目入口；也不一定适合留在聊天记录里，因为聊天记录会被压缩、切换和遗忘。它们更像是一层项目级的“语义索引”。</p><p>如果没有这层索引，Agent 很容易犯两类错误：</p><ol><li>把自己的推断当成用户定义。</li><li>把当前运行状态当成长期项目概念。</li></ol><p>前者会让术语越来越抽象，后者会让词典越来越像流水账。term-keeper 的设计目标，就是把这两件事挡在写入之前。</p><h2 id="term-keeper-的核心规则" tabindex="-1">term-keeper 的核心规则 <a class="header-anchor" href="#term-keeper-的核心规则" aria-label="Permalink to &quot;term-keeper 的核心规则&quot;">​</a></h2><p>term-keeper 是一个可复用的 Codex Skill。它的职责只有一个：维护项目里的长期术语表 / 概念词典。</p><p>它关心的是这些内容：</p><ul><li>业务术语和领域概念。</li><li>模块名称及其含义。</li><li>Agent、角色、岗位或流程边界。</li><li>驾驶舱、报表、指标展示口径。</li><li>流水线状态、交接语义、产物定义。</li><li>已废弃或已改名的旧口径。</li></ul><p>它不应该记录这些内容：</p><ul><li>今天某个任务跑失败了。</li><li>当前批次还没完成。</li><li>某个临时测试结果。</li><li>Agent 自己推断出来的架构理解。</li><li>还没有被用户确认的命名偏好。</li></ul><p>这听起来像文档规范，但对 Agent 来说，它更像是一条操作边界：<strong>不确定就不要写，定义类写入先确认。</strong></p><h2 id="写入前先确认" tabindex="-1">写入前先确认 <a class="header-anchor" href="#写入前先确认" aria-label="Permalink to &quot;写入前先确认&quot;">​</a></h2><p>term-keeper 最重要的流程是确认表。</p><p>当用户明确提出定义、修正、改名、废弃或边界说明时，Agent 不应该直接更新词典，而是先整理成一张表，让用户确认。</p><p><img src="'+p+`" alt="Term Keeper 确认流程图"></p><p>这张表通常会包含：</p><ul><li>术语是什么。</li><li>属于哪类定义。</li><li>准备写入的定义是什么。</li><li>有哪些边界、反例或废弃含义。</li><li>这条定义来自用户哪句话。</li><li>是否影响角色、流程、报表或数据源。</li><li>本次动作是新增、更新还是废弃。</li></ul><p>确认表的意义不是形式感，而是防止 Agent 把“听起来合理”的理解写成长期事实。尤其是当一个定义会影响角色职责、流水线顺序、外部报表口径或数据源时，写入前必须显式确认。</p><h2 id="markdown-给-agent-读-html-给人审" tabindex="-1">Markdown 给 Agent 读，HTML 给人审 <a class="header-anchor" href="#markdown-给-agent-读-html-给人审" aria-label="Permalink to &quot;Markdown 给 Agent 读，HTML 给人审&quot;">​</a></h2><p>term-keeper 默认维护两份文件：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>docs/glossary.md</span></span>
<span class="line"><span>docs/glossary.html</span></span></code></pre></div><p>Markdown 是 Agent 友好的版本。它适合在后续会话中被快速读取，用来判断某个术语是否已有定义、是否有废弃说法、是否存在边界限制。</p><p>HTML 是给人审阅的版本。它不承担复杂交互，只做一件事：把词条清楚地摆成表格。</p><p><img src="`+t+`" alt="Term Keeper HTML 词表截图"></p><p>HTML 表格里会展示术语、类型、定义、来源、维护规则、边界、最后修改时间、触发频率和确认状态。这样用户不用读 Markdown 结构，也能快速检查词典有没有写偏。</p><p>这里有一个小取舍：term-keeper 允许 Agent 直接维护 Markdown 和 HTML。脚本存在，但它们只是辅助工具，用于发布前校验、CI 或批量生成。日常维护时，核心责任仍然在 Agent：写入后要确保两个版本同步。</p><h2 id="触发频率不是热度统计" tabindex="-1">触发频率不是热度统计 <a class="header-anchor" href="#触发频率不是热度统计" aria-label="Permalink to &quot;触发频率不是热度统计&quot;">​</a></h2><p>我给词条加了一个字段：<code>触发频率</code>。</p><p>但它不是全量统计，也不是从历史记录里重新计算出来的热度。它只是一个增量元数据：</p><ul><li>用户在当前项目语境里提到已有词条时，加 1。</li><li>Agent 明确使用已有词条来解释、路由、验证或更新项目工作时，加 1。</li></ul><p>这条规则很克制。它不扫描整个聊天历史，不扫描整个仓库，也不去网上找出现次数。原因很简单：这不是做数据分析，而是给未来 Agent 一个轻量信号，告诉它哪些词在最近的协作中经常被用到。</p><p>如果一个字段会迫使 Agent 做昂贵、模糊、不可复现的统计，它就不适合作为日常维护规则。</p><h2 id="为什么做成-skill-而不是普通提示词" tabindex="-1">为什么做成 Skill，而不是普通提示词 <a class="header-anchor" href="#为什么做成-skill-而不是普通提示词" aria-label="Permalink to &quot;为什么做成 Skill，而不是普通提示词&quot;">​</a></h2><p>普通提示词当然也能写“请维护术语表”。但长期项目里，问题不在于写一次规则，而在于这套规则能不能被稳定复用。</p><p>做成 Skill 之后，它可以把几个东西固定下来：</p><ul><li>触发条件：什么时候应该启用词典维护。</li><li>写入边界：什么能写，什么不能写。</li><li>确认流程：定义类写入必须先给确认表。</li><li>默认路径：没有项目配置时，默认使用 <code>docs/glossary.md</code> 和 <code>docs/glossary.html</code>。</li><li>校验方式：写完后检查 Markdown 和 HTML 是否同步。</li><li>反例：当前运行状态、临时错误、测试批次不应该进入长期词典。</li></ul><p>这让它更像一个小型工作协议，而不是一段会被遗忘的提醒。</p><h2 id="一个典型使用方式" tabindex="-1">一个典型使用方式 <a class="header-anchor" href="#一个典型使用方式" aria-label="Permalink to &quot;一个典型使用方式&quot;">​</a></h2><p>如果项目里还没有词典，用户可以这样说：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请使用 term-keeper，把下面这个定义记录到项目词典：</span></span>
<span class="line"><span>&quot;Agent Router&quot; 指识别请求类型并转交给对应 Agent 的组件。它不是调度器。</span></span></code></pre></div><p>理想行为不是马上写文件，而是先给出确认表：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Term: Agent Router</span></span>
<span class="line"><span>Type: Agent or role boundary</span></span>
<span class="line"><span>Proposed definition: 识别请求类型并转交给对应 Agent 的组件</span></span>
<span class="line"><span>Boundary / deprecated meaning: 不是调度器</span></span>
<span class="line"><span>Impact: roles / workflow</span></span>
<span class="line"><span>Action: add</span></span></code></pre></div><p>用户确认后，Agent 再更新 Markdown 和 HTML。下一次别的会话再遇到 <code>Agent Router</code>，就可以先读词典，而不是重新猜。</p><h2 id="它适合哪些项目" tabindex="-1">它适合哪些项目 <a class="header-anchor" href="#它适合哪些项目" aria-label="Permalink to &quot;它适合哪些项目&quot;">​</a></h2><p>term-keeper 适合那些“项目语义会持续积累”的地方。</p><p>比如：</p><ul><li>多 Agent 协作项目。</li><li>长期维护的产品或系统。</li><li>有大量模块名、状态名、指标名的项目。</li><li>需要保持报表口径一致的项目。</li><li>有明确角色边界和流水线阶段的工作流。</li><li>写作、研究、实验、工程混在一起推进的项目。</li></ul><p>它不适合替代任务管理，也不应该变成运行日志。任务进度、失败记录、当天状态应该进入 issue、看板、日志或日报，而不是进入术语词典。</p><h2 id="当前状态" tabindex="-1">当前状态 <a class="header-anchor" href="#当前状态" aria-label="Permalink to &quot;当前状态&quot;">​</a></h2><p>现在这个项目已经整理成一个可以公开分享的仓库结构：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>term-keeper/</span></span>
<span class="line"><span>  README.md</span></span>
<span class="line"><span>  README.zh-CN.md</span></span>
<span class="line"><span>  INSTALLATION.md</span></span>
<span class="line"><span>  EXAMPLES.md</span></span>
<span class="line"><span>  TESTING.md</span></span>
<span class="line"><span>  AUDIT.md</span></span>
<span class="line"><span>  skill/</span></span>
<span class="line"><span>    term-keeper/</span></span>
<span class="line"><span>      SKILL.md</span></span>
<span class="line"><span>      references/</span></span>
<span class="line"><span>      scripts/</span></span>
<span class="line"><span>      examples/</span></span></code></pre></div><p>真正可安装的是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>skill/term-keeper/</span></span></code></pre></div><p>把这个目录复制到 Codex 的 skills 目录后，就可以在项目里通过 <code>term-keeper</code> 维护词典。</p><p>仓库里也放了两个可选脚本：</p><ul><li><code>render_glossary_html.py</code>：把默认 Markdown 结构渲染成 HTML 表格。</li><li><code>check_dictionary_sync.py</code>：检查 Markdown 和 HTML 里的词条是否同步。</li></ul><p>我还补了最小测试和 CI，用来防止后续修改脚本时破坏渲染和同步检查。</p><h2 id="后续想改进什么" tabindex="-1">后续想改进什么 <a class="header-anchor" href="#后续想改进什么" aria-label="Permalink to &quot;后续想改进什么&quot;">​</a></h2><p>现在的版本更像一个清晰可用的最小闭环。后续如果继续打磨，我会优先考虑三件事。</p><p>第一，给更多真实项目跑压力测试。特别是那些同时涉及角色边界、报表口径和数据源的项目，因为这类定义最容易影响后续决策。</p><p>第二，让 HTML 审阅页更适合长期维护。现在它已经能展示核心字段，但还可以继续优化筛选、搜索和移动端阅读体验。</p><p>第三，整理更多示例。一个 Skill 好不好用，很大程度取决于它能不能通过反例教会 Agent 边界在哪里。比如“今天跑失败了”不该写入，“以后这个状态名表示人工复核中”才应该进入词典。</p><h2 id="结语" tabindex="-1">结语 <a class="header-anchor" href="#结语" aria-label="Permalink to &quot;结语&quot;">​</a></h2><p>我越来越觉得，长期使用 Agent 做项目时，真正重要的不只是上下文长度，而是哪些信息应该沉淀成稳定文件。</p><p>聊天记录适合讨论，任务系统适合追踪进度，代码仓库适合保存实现。项目里的长期语义，也应该有自己的位置。</p><p>term-keeper 想做的就是这件小事：让 Agent 少猜一点，让项目术语少漂移一点。</p>`,75)])])}const k=a(i,[["render",r]]);export{u as __pageData,k as default};
